CREATE TABLE writing_project_state(project_id TEXT PRIMARY KEY REFERENCES projects(id),revision INTEGER NOT NULL DEFAULT 0,core_version_id TEXT,target_snapshot_id TEXT,contract_heads_json TEXT NOT NULL DEFAULT '{}',policy_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE repository_bindings(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),root_path_local TEXT NOT NULL,scope_json TEXT NOT NULL,scope_revision INTEGER NOT NULL DEFAULT 1,egress_policy TEXT NOT NULL DEFAULT 'local_only',created_at TEXT NOT NULL);
CREATE TABLE repository_snapshots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),binding_id TEXT NOT NULL REFERENCES repository_bindings(id),mode TEXT NOT NULL,state TEXT NOT NULL,manifest_blob TEXT,manifest_hash TEXT,head_commit TEXT,capture_window_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE repository_snapshot_files(snapshot_id TEXT NOT NULL REFERENCES repository_snapshots(id),relative_path TEXT NOT NULL,blob_sha256 TEXT NOT NULL,encoding TEXT NOT NULL,line_index_blob TEXT,parse_state TEXT NOT NULL,observed_metadata_json TEXT NOT NULL,PRIMARY KEY(snapshot_id,relative_path));
CREATE TABLE code_units(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),snapshot_id TEXT NOT NULL REFERENCES repository_snapshots(id),relative_path TEXT NOT NULL,kind TEXT NOT NULL,symbol TEXT NOT NULL,line_start INTEGER NOT NULL,line_end INTEGER NOT NULL,text_hash TEXT NOT NULL,parser_version TEXT NOT NULL);
CREATE INDEX idx_code_units_snapshot ON code_units(snapshot_id,relative_path);
CREATE TABLE code_edges(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES repository_snapshots(id),from_unit_id TEXT NOT NULL REFERENCES code_units(id),to_unit_id TEXT REFERENCES code_units(id),relation TEXT NOT NULL,resolution_state TEXT NOT NULL,evidence_json TEXT NOT NULL);
CREATE TABLE evidence_items(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,origin_type TEXT NOT NULL,origin_id TEXT NOT NULL,origin_version TEXT NOT NULL,locator_json TEXT NOT NULL,payload_hash TEXT NOT NULL,conditions_json TEXT NOT NULL,validity TEXT NOT NULL DEFAULT 'current',created_at TEXT NOT NULL);
CREATE TABLE claim_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),claim_key TEXT NOT NULL,revision INTEGER NOT NULL,kind TEXT NOT NULL,proposition_json TEXT NOT NULL,source_state TEXT NOT NULL DEFAULT 'candidate',created_at TEXT NOT NULL,UNIQUE(project_id,claim_key,revision));
CREATE TABLE claim_evidence_links(claim_version_id TEXT NOT NULL REFERENCES claim_versions(id),evidence_id TEXT NOT NULL REFERENCES evidence_items(id),relation TEXT NOT NULL,scope_json TEXT NOT NULL,PRIMARY KEY(claim_version_id,evidence_id,relation));
CREATE TABLE thesis_core_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),parent_id TEXT REFERENCES thesis_core_versions(id),content_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE section_contract_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),section_id TEXT NOT NULL REFERENCES sections(id),parent_id TEXT REFERENCES section_contract_versions(id),content_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL);
